{
  "correction_rules": [
    "Adjust forecasts downward if sentiment is consistently negative or neutral over recent days, indicating market cooling.",
    "Reduce forecast magnitude after a sharp spike in price — model tends to overreact and overshoot.",
    "Apply mean reversion bias: if forecast is significantly above recent 5-10 day average, reduce by 5-15% to align with historical volatility.",
    "If sentiment is positive but forecast is excessively high, apply a downward correction proportional to sentiment strength (e.g., 10-20% if sentiment > 0.3).",
    "For horizon > 14 days, reduce forecast sensitivity to recent spikes — model overfits short-term momentum.",
    "If true outcome is consistently below forecast, especially after a positive sentiment period, consider a ‘reversion-to-mean’ correction rule."
  ]
}

